  id: string;
  workspaceId: string;
  deploymentId: string;
  target: {
    type: ReviewTargetType;
    workspaceId: string;
    deploymentId: string;
  };
  mode: ReviewMode;
  status: ReviewStatus;
  idempotencyKey: string;
  attemptCount: number;
  derivedPolicy?: ReviewPolicyDraft;
  approvedPolicy?: ReviewPolicyDraft;
  approvedPolicySha256?: string;
  createdAt: string;
  updatedAt: string;
  startedAt: string | null;
  finishedAt: string | null;
  summary?: ReviewSummary;
  summaryText?: string;
  furtherPassesLowYield?: boolean;
  findings: ReviewFinding[];
  intent?: ReviewIntentSummary;
  evidence: ReviewEvidence[];
  provenance: ReviewProvenanceSummary;
  markdownSummary: string | null;
  error?: {
    code: string;
    message: string;
  };
}

export interface GetReviewResponse {
  review: ReviewResponse;
}

export interface ReviewHistoryItem {
  id: string;
  workspaceId: string;
  deploymentId: string;
  repo: string;
  branch: string;
  status: ReviewStatus;
  createdAt: string;
  updatedAt: string;
  startedAt: string | null;
  finishedAt: string | null;
  findingCount: number | null;
  riskLevel: 'critical' | 'high' | 'medium' | 'low' | null;
  recommendation: ReviewRecommendation | null;
  summaryText: string | null;
  error?: {
    code: string;
    message: string;
  };
}

export interface ListReviewsResponse {
  reviews: ReviewHistoryItem[];
}

export interface StudioContextResponse {
  repo: string | null;
  branch: string | null;
  detectedAt: string;
}

export type StudioPolicyMode = 'auto' | 'review';

export interface StudioNewReviewPreflightCheck {
  code: 'checkpoint' | 'entire_context';
  label: string;
  ok: boolean;
  detail: string;
}

