    execFileSync('git', ['merge-base', '--is-ancestor', ancestorRef, descendantRef], {
      cwd: repoRoot,
      stdio: 'ignore',
    });
    return true;
  } catch (error) {
    if (error && typeof error === 'object' && 'status' in error) {
