    case 'risky_fix_requires_approval':
      return 'converged_with_blockers';
    case 'initial_pass_failed':
    case 'followup_pass_failed':
    case 'auto_remediation_failed':
    case 'no_safe_fixes':
      return 'blocked';
    case 'diminishing_returns':
    case 'no_progress':
    case 'max_repair_cycles_reached':
