+  label: string;
+  detail?: string;
+}
+
+const EVENT_LABELS: Record<string, string> = {
+  review_created: 'Review created',
+  review_enqueued: 'Queued for execution',
+  review_policy_derivation_started: 'Deriving policy from session context',
+  review_policy_derivation_completed: 'Policy draft ready',
+  review_policy_approved: 'Policy approved',
+  review_context_assembly_started: 'Assembling review context',
+  review_context_assembly_succeeded: 'Context assembly finished',
+  review_context_assembly_failed: 'Context assembly failed',
+  review_analysis_started: 'Analysis started',
+  review_finding_emitted: 'Finding emitted',
+  review_auto_remediation_planned: 'Remediation planned',
+  review_auto_remediation_started: 'Applying safe remediation',
+  review_auto_remediation_completed: 'Remediation finished',
+  review_auto_remediation_failed: 'Remediation failed',
+  review_auto_remediation_skipped: 'Remediation skipped',
+  review_followup_planned: 'Follow-up pass planned',
+  review_succeeded: 'Pass completed',
+  review_failed: 'Pass failed',
+  review_cancelled: 'Pass cancelled',
+};
+
+function sessionPath(input: { sessionId: string; repo?: string; branch?: string }): string {
+  if (input.repo && input.branch) {
+    return `/branches/${encodeURIComponent(input.repo)}/${encodeURIComponent(input.branch)}/sessions/${encodeURIComponent(
+      input.sessionId
+    )}`;
+  }
+  return `/sessions/${encodeURIComponent(input.sessionId)}`;
+}
+
+function sessionReportPath(input: { sessionId: string; reviewId: string; repo?: string; branch?: string }): string {
+  return `${sessionPath(input)}/reports/${encodeURIComponent(input.reviewId)}`;
+}
+
+function isTerminalSessionPhase(phase: ReviewSessionResponse['phase'] | null | undefined): boolean {
+  return phase === 'completed' || phase === 'failed' || phase === 'cancelled' || phase === 'waiting_on_human';
+}
+
+function sessionPhaseLabel(phase: ReviewSessionResponse['phase']): string {
+  return phase.replace(/_/g, ' ');
+}
+
+function sessionPhaseClass(phase: ReviewSessionResponse['phase']): string {
+  if (phase === 'completed') {
+    return 'border-emerald-200 bg-emerald-50 text-emerald-900';
+  }
+  if (phase === 'failed' || phase === 'cancelled') {
+    return 'border-rose-200 bg-rose-50 text-rose-900';
+  }
+  if (phase === 'waiting_on_human') {
+    return 'border-amber-200 bg-amber-50 text-amber-900';
+  }
+  return 'border-sky-200 bg-sky-50 text-sky-900';
+}
+
+function contextModeLabel(value: 'basic' | 'intent_aware' | null | 'unknown' | undefined): string {
+  if (value === 'intent_aware') {
+    return 'Intent-aware';
+  }
+  if (value === 'basic') {
+    return 'Basic';
+  }
+  if (value === 'unknown') {
+    return 'Unknown';
+  }
+  return 'Pending';
+}
+
+function stopReasonLabel(value: ReviewSessionResponse['stopReason']): string {
+  if (!value) {
+    return 'Active';
+  }
+  return value.replace(/_/g, ' ');
+}
+
+function relativeTime(value: string | null): string {
+  if (!value) {
+    return 'unknown';
+  }
+  const then = Date.parse(value);
+  if (Number.isNaN(then)) {
+    return 'unknown';
+  }
+  const diffMs = Date.now() - then;
+  const absSeconds = Math.floor(Math.abs(diffMs) / 1000);
+  if (absSeconds < 60) {
+    return 'just now';
+  }
+  const inFuture = diffMs < 0;
+  const absMinutes = Math.floor(absSeconds / 60);
+  if (absMinutes < 60) {
+    return inFuture ? `in ${absMinutes}m` : `${absMinutes}m ago`;
+  }
+  const absHours = Math.floor(absMinutes / 60);
+  if (absHours < 24) {
+    return inFuture ? `in ${absHours}h` : `${absHours}h ago`;
+  }
+  const absDays = Math.floor(absHours / 24);
+  return inFuture ? `in ${absDays}d` : `${absDays}d ago`;
+}
+
+function createEditablePolicyDraft(policy: ReviewPolicyDraft | undefined): EditablePolicyDraft {
+  return {
+    goal: policy?.goal ?? '',
+    prohibitions: (policy?.prohibitions ?? []).join('\n'),
+    constraints: (policy?.constraints ?? []).join('\n'),
+  };
+}
+
+function normalizeEditablePolicyDraft(policy: EditablePolicyDraft): ReviewPolicyDraft {
+  const normalizeLines = (value: string): string[] =>
+    Array.from(
+      new Set(
+        value
+          .split('\n')
+          .map((item) => item.trim())
+          .filter(Boolean)
+      )
+    );
+
+  const goal = policy.goal.trim();
+  return {
+    goal: goal ? goal : null,
+    prohibitions: normalizeLines(policy.prohibitions),
+    constraints: normalizeLines(policy.constraints),
+  };
+}
+
+function findingKey(finding: Pick<ReviewFinding, 'severity' | 'category' | 'description' | 'locations'>): string {
+  const location = finding.locations[0]?.filePath ?? '';
+  return `${finding.severity}::${finding.category}::${finding.description}::${location}`;
+}
+
+function summarizeResolvedFindings(reviews: ReviewResponse[], latestReviewId: string | null): ReviewFinding[] {
+  if (!latestReviewId || reviews.length < 2) {
+    return [];
+  }
+
+  const latestReview = reviews.find((review) => review.id === latestReviewId) ?? reviews[reviews.length - 1];
+  if (!latestReview) {
+    return [];
+  }
+
+  const unresolvedKeys = new Set(latestReview.findings.map((finding) => findingKey(finding)));
+  const resolved = new Map<string, ReviewFinding>();
+  for (const review of reviews) {
+    if (review.id === latestReview.id) {
+      continue;
+    }
+    for (const finding of review.findings) {
+      const key = findingKey(finding);
+      if (!unresolvedKeys.has(key) && !resolved.has(key)) {
+        resolved.set(key, finding);
+      }
+    }
+  }
+  return [...resolved.values()];
+}
+
+function eventToActivityEntry(data: Record<string, unknown>): ActivityEntry | null {
+  const eventType = typeof data.type === 'string' ? data.type : '';
+  if (!eventType || eventType === 'heartbeat' || eventType === 'snapshot' || eventType === 'terminal') {
+    return null;
+  }
+
+  let detail: string | undefined;
+  if (eventType === 'review_finding_emitted' && typeof data.description === 'string') {
+    detail = data.description;
+  } else if (eventType === 'review_succeeded' && typeof data.findingCount === 'number') {
+    detail = `${data.findingCount} finding${data.findingCount === 1 ? '' : 's'}`;
+  } else if (typeof data.message === 'string' && data.message.trim()) {
+    detail = data.message;
+  }
+
+  return {
+    id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
+    timestamp: Date.now(),
+    label: EVENT_LABELS[eventType] ?? eventType.replace(/_/g, ' '),
+    detail,
+  };
+}
+
+function findingsHeader(session: ReviewSessionResponse, latestReview: ReviewResponse | null): string {
+  if (!latestReview || latestReview.findings.length === 0) {
+    return session.outcome?.unresolved.findingCount
+      ? `${session.outcome.unresolved.findingCount} remaining`
+      : 'No remaining findings';
+  }
+  return `${latestReview.findings.length} remaining finding${latestReview.findings.length === 1 ? '' : 's'}`;
+}
+
+function diffSummaryLabel(diff: WorkspaceDiffResponse | null): string {
+  if (!diff) {
+    return 'No reviewed diff available.';
+  }
+  return `${diff.summary.totalChanged} changed file${diff.summary.totalChanged === 1 ? '' : 's'} • ${diff.summary.added} added • ${diff.summary.modified} modified • ${diff.summary.deleted} deleted`;
+}
+
+export function ReviewSessionPage(): JSX.Element {
+  const { sessionId = '', repo, branch } = useParams<{ sessionId: string; repo?: string; branch?: string }>();
+  const activitySourceRef = useRef<EventSource | null>(null);
