  const [remoteDiffError, setRemoteDiffError] = useState<string | null>(null);
  const [localEnvironments, setLocalEnvironments] = useState<LocalReviewEnvironment[]>([]);
  const [selectedLocalKey, setSelectedLocalKey] = useState<string | null>(null);
  const [localDiff, setLocalDiff] = useState<LocalReviewEnvironmentDiffResponse | null>(null);
  const [localDiffError, setLocalDiffError] = useState<string | null>(null);
  const [localActionMessage, setLocalActionMessage] = useState<string | null>(null);
  const [localActionError, setLocalActionError] = useState<string | null>(null);
  const [adoptingMode, setAdoptingMode] = useState<'branch' | 'worktree' | null>(null);
  const [mergeBackRunning, setMergeBackRunning] = useState(false);
  const [approvingPolicy, setApprovingPolicy] = useState(false);
  const [policyActionError, setPolicyActionError] = useState<string | null>(null);
  const [policyDraft, setPolicyDraft] = useState<EditablePolicyDraft>({
    goal: '',
    prohibitions: '',
    constraints: '',
  });
  const policyDraftTouched = useRef(false);

  const fetchSession = useCallback(async () => {
    const response = await fetch(`${API_BASE}/api/review-sessions/${encodeURIComponent(sessionId)}`);
    if (!response.ok) {
      const body = (await response.json().catch(() => null)) as { error?: string } | null;
      throw new Error(body?.error ?? `Failed to load review session (${response.status})`);
    }
    const payload = parseGetReviewSessionResponse(await response.json());
    const nextSession = payload.session;

    const reviewResponses = await Promise.all(
      nextSession.passes.map(async (pass) => {
        const reviewResponse = await fetch(`${API_BASE}/api/reviews/${encodeURIComponent(pass.reviewId)}`);
        if (!reviewResponse.ok) {
          const body = (await reviewResponse.json().catch(() => null)) as { error?: string } | null;
          throw new Error(body?.error ?? `Failed to load review ${pass.reviewId} (${reviewResponse.status})`);
        }
        return parseGetReviewResponse(await reviewResponse.json()).review;
      })
    );

    setSession(nextSession);
    setReviewsById(
      Object.fromEntries(reviewResponses.map((review) => [review.id, review]))
    );
    setExpandedPasses((current) => {
      const next = { ...current };
      for (const pass of nextSession.passes) {
        if (!(pass.reviewId in next)) {
          next[pass.reviewId] = pass.reviewId === nextSession.latestReviewId;
        }
      }
      if (nextSession.latestReviewId) {
        next[nextSession.latestReviewId] = true;
      }
      return next;
    });
    setErrorMessage(null);
  }, [sessionId]);

  const fetchLocalEnvironments = useCallback(async () => {
    const response = await fetch(
      `${API_BASE}/api/studio/local-review-sessions?sessionId=${encodeURIComponent(sessionId)}`
    );
    if (!response.ok) {
      const body = (await response.json().catch(() => null)) as { error?: string } | null;
      throw new Error(body?.error ?? `Failed to load local environments (${response.status})`);
    }
    const payload = parseLocalReviewEnvironmentListResponse(await response.json());
    setLocalEnvironments(payload.environments);
    setSelectedLocalKey((current) => {
      if (current && payload.environments.some((entry) => `${entry.branchName}:${entry.mode}` === current)) {
        return current;
      }
      return payload.environments[0] ? `${payload.environments[0].branchName}:${payload.environments[0].mode}` : null;
    });
  }, [sessionId]);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        await Promise.all([fetchSession(), fetchLocalEnvironments()]);
      } catch (error) {
        if (!cancelled) {
          setErrorMessage(error instanceof Error ? error.message : String(error));
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };
    void load();
    return () => {
      cancelled = true;
    };
  }, [fetchLocalEnvironments, fetchSession]);

  useEffect(() => {
    if (!session || isTerminalSessionPhase(session.phase)) {
      return;
    }

    const timer = window.setInterval(() => {
      void fetchSession().catch((error) => {
        setErrorMessage(error instanceof Error ? error.message : String(error));
      });
    }, 4_000);
    return () => {
      window.clearInterval(timer);
    };
  }, [fetchSession, session]);

  useEffect(() => {
    const activeReviewId = session?.activeReviewId;
    const status = session?.currentReviewStatus;
    if (!activeReviewId || !status || !ACTIVE_REVIEW_STATUSES.has(status)) {
      activitySourceRef.current?.close();
      activitySourceRef.current = null;
      return;
    }

    activitySourceRef.current?.close();
    const source = new EventSource(`${API_BASE}/api/reviews/${encodeURIComponent(activeReviewId)}/events`);
    activitySourceRef.current = source;
    source.addEventListener('message', (event: MessageEvent<string>) => {
      try {
        const data = JSON.parse(event.data) as Record<string, unknown>;
        const activityEntry = eventToActivityEntry(data);
        if (activityEntry) {
          setActivity((current) => [activityEntry, ...current].slice(0, 20));
        }
        if (data.type === 'terminal' || data.type === 'snapshot') {
          void fetchSession().catch(() => undefined);
        }
      } catch {
        // best-effort activity stream
      }
    });
    source.addEventListener('error', () => {
      source.close();
    });
    return () => {
      source.close();
      if (activitySourceRef.current === source) {
        activitySourceRef.current = null;
      }
    };
  }, [fetchSession, session?.activeReviewId, session?.currentReviewStatus]);

  useEffect(() => {
    return () => {
      activitySourceRef.current?.close();
      activitySourceRef.current = null;
    };
  }, []);

  useEffect(() => {
    if (!session || !isTerminalSessionPhase(session.phase) || !(session.outcome?.changes.changedFileCount ?? 0)) {
      setRemoteDiff(null);
      setRemoteDiffError(null);
      return;
    }

    let cancelled = false;
    const load = async () => {
      try {
        const response = await fetch(
          `${API_BASE}/api/workspaces/${encodeURIComponent(session.workspaceId)}/diff?include_patch=1&max_bytes=200000`
        );
        if (!response.ok) {
          const body = (await response.json().catch(() => null)) as { error?: string } | null;
          throw new Error(body?.error ?? `Failed to load reviewed diff (${response.status})`);
        }
        const payload = parseWorkspaceDiffResponse(await response.json());
        if (!cancelled) {
          setRemoteDiff(payload);
          setRemoteDiffError(null);
        }
      } catch (error) {
        if (!cancelled) {
          setRemoteDiff(null);
          setRemoteDiffError(error instanceof Error ? error.message : String(error));
        }
      }
    };
    void load();
    return () => {
      cancelled = true;
    };
  }, [session]);

  const selectedLocalEnvironment = useMemo(() => {
    if (!selectedLocalKey) {
      return null;
    }
    return localEnvironments.find((entry) => `${entry.branchName}:${entry.mode}` === selectedLocalKey) ?? null;
  }, [localEnvironments, selectedLocalKey]);

  useEffect(() => {
    if (!selectedLocalEnvironment) {
      setLocalDiff(null);
      setLocalDiffError(null);
      return;
    }

    let cancelled = false;
    const load = async () => {
      try {
        const params = new URLSearchParams({
          baseRef: 'HEAD',
          branchName: selectedLocalEnvironment.branchName,
          mode: selectedLocalEnvironment.mode,
        });
        const response = await fetch(
          `${API_BASE}/api/studio/local-review-sessions/${encodeURIComponent(
            selectedLocalEnvironment.sessionId
          )}/diff?${params.toString()}`
        );
        if (!response.ok) {
          const body = (await response.json().catch(() => null)) as { error?: string } | null;
          throw new Error(body?.error ?? `Failed to load local diff (${response.status})`);
        }
        const payload = parseLocalReviewEnvironmentDiffResponse(await response.json());
        if (!cancelled) {
          setLocalDiff(payload);
          setLocalDiffError(null);
        }
      } catch (error) {
        if (!cancelled) {
          setLocalDiff(null);
          setLocalDiffError(error instanceof Error ? error.message : String(error));
        }
      }
    };
    void load();
    return () => {
      cancelled = true;
    };
  }, [selectedLocalEnvironment]);

  const activeReview = useMemo(
    () => (session?.activeReviewId ? reviewsById[session.activeReviewId] ?? null : null),
    [reviewsById, session]
  );

  const latestReview = useMemo(
    () => (session?.latestReviewId ? reviewsById[session.latestReviewId] ?? null : null),
    [reviewsById, session]
  );

  useEffect(() => {
    if (!activeReview || activeReview.status !== 'policy_ready' || policyDraftTouched.current) {
      return;
    }
    setPolicyDraft(createEditablePolicyDraft(activeReview.derivedPolicy));
  }, [activeReview]);

  const orderedReviews = useMemo(() => {
    if (!session) {
      return [];
    }
    return session.passes
      .map((pass) => reviewsById[pass.reviewId])
      .filter((review): review is ReviewResponse => Boolean(review));
  }, [reviewsById, session]);

  const resolvedFindings = useMemo(
    () => summarizeResolvedFindings(orderedReviews, session?.latestReviewId ?? null),
    [orderedReviews, session?.latestReviewId]
  );

  const unresolvedFindings = useMemo(() => {
    if (!isTerminalSessionPhase(session?.phase) || !latestReview || latestReview.status !== 'succeeded') {
      return [];
    }
    return latestReview.findings;
  }, [latestReview, session?.phase]);

  const handleApprovePolicy = useCallback(async () => {
    if (!activeReview || activeReview.status !== 'policy_ready' || approvingPolicy) {
      return;
    }
    setApprovingPolicy(true);
    setPolicyActionError(null);
    try {
      const approvedPolicy = normalizeEditablePolicyDraft(policyDraft);
      const response = await fetch(`${API_BASE}/api/reviews/${encodeURIComponent(activeReview.id)}/policy/approve`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ approvedPolicy }),
      });
      if (!response.ok) {
        const body = (await response.json().catch(() => null)) as { error?: string } | null;
        throw new Error(body?.error ?? `Failed to approve policy (${response.status})`);
      }
      policyDraftTouched.current = false;
      await fetchSession();
    } catch (error) {
      setPolicyActionError(error instanceof Error ? error.message : String(error));
    } finally {
      setApprovingPolicy(false);
    }
  }, [activeReview, approvingPolicy, fetchSession, policyDraft]);

  const handleAdopt = useCallback(
    async (mode: 'worktree' | 'branch') => {
      if (!session) {
        return;
      }
      setAdoptingMode(mode);
      setLocalActionError(null);
      setLocalActionMessage(null);
      try {
        const response = await fetch(
          `${API_BASE}/api/studio/local-review-sessions/${encodeURIComponent(session.id)}/adopt`,
          {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({ mode }),
          }
        );
        const body = (await response.json().catch(() => null)) as { error?: string; branchName?: string } | null;
        if (!response.ok) {
          throw new Error(body?.error ?? `Failed to adopt session (${response.status})`);
        }
        await fetchLocalEnvironments();
        setLocalActionMessage(
          mode === 'worktree'
            ? `Adopted into an isolated worktree${body?.branchName ? ` on ${body.branchName}` : ''}.`
            : `Adopted into local branch ${body?.branchName ?? 'nimbus/session'}.`
        );
      } catch (error) {
        setLocalActionError(error instanceof Error ? error.message : String(error));
      } finally {
        setAdoptingMode(null);
      }
    },
    [fetchLocalEnvironments, session]
  );

  const handleMergeBack = useCallback(async () => {
    if (!selectedLocalEnvironment) {
      return;
    }
    setMergeBackRunning(true);
    setLocalActionError(null);
    setLocalActionMessage(null);
    try {
      const params = new URLSearchParams({
        branchName: selectedLocalEnvironment.branchName,
        mode: selectedLocalEnvironment.mode,
      });
      const response = await fetch(
        `${API_BASE}/api/studio/local-review-sessions/${encodeURIComponent(
          selectedLocalEnvironment.sessionId
        )}/merge-back?${params.toString()}`,
        {
          method: 'POST',
        }
      );
      const body = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error((body as { error?: string } | null)?.error ?? `Failed to merge back session (${response.status})`);
      }
      const payload = parseLocalReviewEnvironmentMergeBackResponse(body);
      setLocalActionMessage(
        payload.status === 'already_applied'
          ? `Session ${payload.sessionId} is already applied on ${payload.currentBranch}.`
          : `Applied session ${payload.sessionId} onto ${payload.currentBranch}.`
      );
    } catch (error) {
      setLocalActionError(error instanceof Error ? error.message : String(error));
    } finally {
      setMergeBackRunning(false);
    }
  }, [selectedLocalEnvironment]);

  if (loading) {
    return (
      <main className="mx-auto flex w-full max-w-[1200px] flex-col gap-3 px-3 py-3">
        <div className="space-y-3 text-center">
          <p className="text-xs uppercase tracking-[0.08em] text-muted-foreground">Review Session</p>
          <h1 className="policy-heading text-base text-foreground">Loading session</h1>
        </div>
      </main>
    );
  }

  if (errorMessage || !session) {
    return (
      <main className="mx-auto flex w-full max-w-[1200px] flex-col gap-3 px-3 py-3">
        <Card className="p-4">
          <h1 className="text-base font-semibold text-foreground">Unable to load review session</h1>
          <p className="mt-2 text-sm text-muted-foreground">{errorMessage ?? 'Session data is unavailable.'}</p>
        </Card>
      </main>
    );
  }

  const sessionBasePath = sessionPath({ sessionId: session.id, repo, branch });
  const showTerminalSections = isTerminalSessionPhase(session.phase);
  const showPolicyGate =
    activeReview && (activeReview.status === 'policy_pending' || activeReview.status === 'policy_ready' || activeReview.status === 'policy_approved');

  return (
    <main className="mx-auto flex w-full max-w-[1200px] flex-col gap-3 px-3 py-3">
      <nav className="flex items-center gap-2 text-xs text-muted-foreground">
        <Link to="/" className="hover:text-foreground">
          Studio Home
        </Link>
        <span>/</span>
        {repo && branch ? (
          <>
            <Link to={`/branches/${encodeURIComponent(repo)}/${encodeURIComponent(branch)}`} className="hover:text-foreground">
              Branch {branch}
            </Link>
            <span>/</span>
          </>
        ) : null}
        <span className="text-foreground">{session.id}</span>
      </nav>

      <Card className="p-4">
        <div className="flex flex-col gap-4">
          <div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between">
            <div className="space-y-2">
              <div className="flex flex-wrap items-center gap-2">
                <Badge variant="outline" className={cn('rounded-full px-2 py-0.5 text-[10px] uppercase tracking-[0.08em]', sessionPhaseClass(session.phase))}>
                  {sessionPhaseLabel(session.phase)}
                </Badge>
                {session.currentReviewStatus ? <StatusPill status={session.currentReviewStatus} /> : null}
                <Badge variant="outline" className="rounded-full px-2 py-0.5 text-[10px]">
                  {contextModeLabel(session.outcome?.reviewed.contextMode ?? null)}
                </Badge>
                <Badge variant="outline" className="rounded-full px-2 py-0.5 text-[10px]">
                  {session.passCount} pass{session.passCount === 1 ? '' : 'es'}
                </Badge>
              </div>
              <div>
                <h1 className="policy-heading text-lg text-foreground">Review session {session.id}</h1>
                <p className="mt-1 text-sm text-muted-foreground">
                  {session.repo} • {session.branch}
                </p>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-2 text-sm md:min-w-[320px]">
              <div className="rounded-sm border border-border/70 bg-card/70 px-3 py-2">
                <p className="text-[11px] uppercase tracking-[0.08em] text-muted-foreground">Latest pass</p>
                <p className="mt-1 font-semibold text-foreground">{session.latestReviewId ?? 'none'}</p>
              </div>
              <div className="rounded-sm border border-border/70 bg-card/70 px-3 py-2">
                <p className="text-[11px] uppercase tracking-[0.08em] text-muted-foreground">Stop reason</p>
                <p className="mt-1 font-semibold text-foreground">{stopReasonLabel(session.stopReason)}</p>
              </div>
              <div className="rounded-sm border border-border/70 bg-card/70 px-3 py-2">
                <p className="text-[11px] uppercase tracking-[0.08em] text-muted-foreground">Updated</p>
                <p className="mt-1 font-semibold text-foreground">{relativeTime(session.updatedAt)}</p>
              </div>
              <div className="rounded-sm border border-border/70 bg-card/70 px-3 py-2">
                <p className="text-[11px] uppercase tracking-[0.08em] text-muted-foreground">Anchor commit</p>
                <p className="mt-1 font-mono text-xs text-foreground">{session.anchorCommitSha?.slice(0, 12) ?? 'none'}</p>
              </div>
            </div>
          </div>
          <p className="text-sm text-muted-foreground">
            {showTerminalSections
              ? session.outcome?.summary ?? 'Session reached a terminal state.'
              : 'Nimbus is still working through this session. Activity and latest-pass detail stay live until the session stops.'}
          </p>
        </div>
      </Card>

      {showPolicyGate ? (
        <Card className="p-4">
          {activeReview?.status === 'policy_pending' ? (
            <div className="space-y-2">
              <p className="text-xs uppercase tracking-[0.08em] text-muted-foreground">Policy gate</p>
              <h2 className="text-sm font-semibold text-foreground">Preparing policy draft</h2>
              <p className="text-sm text-muted-foreground">
                Nimbus is deriving a policy from session context before the first pass begins.
              </p>
            </div>
          ) : activeReview?.status === 'policy_ready' ? (
            <div className="space-y-3">
              <div>
                <p className="text-xs uppercase tracking-[0.08em] text-muted-foreground">Policy gate</p>
                <h2 className="text-sm font-semibold text-foreground">Review and approve policy</h2>
                <p className="mt-1 text-sm text-muted-foreground">
                  This session is waiting on human approval before execution. Editing here keeps the session route primary.
                </p>
              </div>
              <label className="block space-y-1 text-sm">
                <span className="font-medium text-foreground">Goal</span>
                <textarea
                  value={policyDraft.goal}
                  onChange={(event) => {
                    policyDraftTouched.current = true;
                    setPolicyDraft((current) => ({ ...current, goal: event.target.value }));
                  }}
                  rows={3}
                  className="w-full rounded-sm border border-border bg-background px-3 py-2 text-sm text-foreground outline-none focus:border-foreground/30"
                />
              </label>
              <div className="grid gap-3 md:grid-cols-2">
                <label className="block space-y-1 text-sm">
                  <span className="font-medium text-foreground">Prohibitions</span>
                  <textarea
                    value={policyDraft.prohibitions}
                    onChange={(event) => {
                      policyDraftTouched.current = true;
                      setPolicyDraft((current) => ({ ...current, prohibitions: event.target.value }));
                    }}
                    rows={6}
                    className="w-full rounded-sm border border-border bg-background px-3 py-2 text-sm text-foreground outline-none focus:border-foreground/30"
                  />
                </label>
                <label className="block space-y-1 text-sm">
                  <span className="font-medium text-foreground">Constraints</span>
                  <textarea
                    value={policyDraft.constraints}
                    onChange={(event) => {
                      policyDraftTouched.current = true;
                      setPolicyDraft((current) => ({ ...current, constraints: event.target.value }));
                    }}
                    rows={6}
                    className="w-full rounded-sm border border-border bg-background px-3 py-2 text-sm text-foreground outline-none focus:border-foreground/30"
                  />
                </label>
              </div>
              {policyActionError ? <p className="text-sm text-destructive">{policyActionError}</p> : null}
              <div className="flex flex-wrap items-center gap-2">
                <Button size="sm" onClick={() => void handleApprovePolicy()} disabled={approvingPolicy}>
                  {approvingPolicy ? 'Approving…' : 'Approve policy'}
                </Button>
                <Link to={sessionReportPath({ sessionId: session.id, reviewId: activeReview.id, repo, branch })}>
                  <Button size="sm" variant="outline">
                    Open pass artifact
                  </Button>
                </Link>
              </div>
            </div>
          ) : (
            <div className="space-y-2">
              <p className="text-xs uppercase tracking-[0.08em] text-muted-foreground">Policy gate</p>
              <h2 className="text-sm font-semibold text-foreground">Policy approved</h2>
              <p className="text-sm text-muted-foreground">
                Nimbus is handing the approved policy to execution. Stay on this session route while the pass starts.
              </p>
            </div>
          )}
        </Card>
      ) : null}

      {!showTerminalSections ? (
        <Card className="p-4">
          <div className="space-y-3">
            <div>
              <p className="text-xs uppercase tracking-[0.08em] text-muted-foreground">Session activity</p>
              <h2 className="text-sm font-semibold text-foreground">Live process view</h2>
            </div>
            {activity.length === 0 ? (
              <p className="text-sm text-muted-foreground">Nimbus will stream pass and remediation activity here as events arrive.</p>
            ) : (
              <div className="space-y-2">
                {activity.map((entry) => (
                  <div key={entry.id} className="rounded-sm border border-border/70 bg-card/70 px-3 py-2">
                    <div className="flex items-center justify-between gap-3">
                      <p className="text-sm font-medium text-foreground">{entry.label}</p>
                      <span className="text-xs text-muted-foreground">{relativeTime(new Date(entry.timestamp).toISOString())}</span>
                    </div>
                    {entry.detail ? <p className="mt-1 text-sm text-muted-foreground">{entry.detail}</p> : null}
                  </div>
                ))}
              </div>
            )}
          </div>
        </Card>
      ) : null}

      {showTerminalSections ? (
        <>
          <Card className="p-4">
            <div className="space-y-3">
              <div>
                <p className="text-xs uppercase tracking-[0.08em] text-muted-foreground">Outcome</p>
                <h2 className="text-sm font-semibold text-foreground">Terminal session summary</h2>
              </div>
              <div className="grid gap-2 md:grid-cols-2">
                <div className="rounded-sm border border-border/70 bg-card/70 px-3 py-2">
                  <p className="text-[11px] uppercase tracking-[0.08em] text-muted-foreground">Outcome kind</p>
                  <p className="mt-1 font-semibold text-foreground">{session.outcome?.kind.replace(/_/g, ' ') ?? 'none'}</p>
                </div>
                <div className="rounded-sm border border-border/70 bg-card/70 px-3 py-2">
                  <p className="text-[11px] uppercase tracking-[0.08em] text-muted-foreground">Recommendation</p>
                  <p className="mt-1 font-semibold text-foreground">{session.outcome?.recommendation?.replace(/_/g, ' ') ?? 'none'}</p>
                </div>
                <div className="rounded-sm border border-border/70 bg-card/70 px-3 py-2">
                  <p className="text-[11px] uppercase tracking-[0.08em] text-muted-foreground">Residual risk</p>
                  <p className="mt-1 font-semibold text-foreground">{session.outcome?.residualRisk ?? 'none'}</p>
                </div>
                <div className="rounded-sm border border-border/70 bg-card/70 px-3 py-2">
                  <p className="text-[11px] uppercase tracking-[0.08em] text-muted-foreground">Evidence</p>
                  <p className="mt-1 font-semibold text-foreground">
                    {session.outcome
                      ? `${session.outcome.evidence.passed} passed • ${session.outcome.evidence.warning} warning • ${session.outcome.evidence.failed} failed`
                      : 'none'}
                  </p>
                </div>
              </div>
              {session.outcome?.summary ? <p className="text-sm text-muted-foreground">{session.outcome.summary}</p> : null}
            </div>
          </Card>

          <Card className="p-4">
            <div className="space-y-3">
              <div>
                <p className="text-xs uppercase tracking-[0.08em] text-muted-foreground">Remaining issues</p>
                <h2 className="text-sm font-semibold text-foreground">{findingsHeader(session, latestReview)}</h2>
              </div>
              {unresolvedFindings.length === 0 ? (
                <p className="text-sm text-muted-foreground">
                  {session.outcome?.unresolved.findingCount
                    ? `${session.outcome.unresolved.findingCount} unresolved findings remain, but the latest pass detail is unavailable.`
                    : 'Nimbus ended this session without remaining findings in the latest pass.'}
                </p>
              ) : (
                <div className="space-y-2">
                  {unresolvedFindings.map((finding, index) => (
