                      </div>
                      <p className="text-sm font-medium text-foreground">{review?.summaryText ?? `Review ${pass.reviewId}`}</p>
                      <p className="text-xs text-muted-foreground">
                        Created {dateTimeLabel(pass.createdAt)} • Finished {dateTimeLabel(pass.finishedAt)}
                      </p>
                    </div>
                    <span className="text-xs text-muted-foreground">{expanded ? 'Collapse' : 'Expand'}</span>
                  </button>
                  {expanded ? (
                    <div className="border-t border-border/60 px-3 py-3">
                      {review ? (
                        <div className="space-y-3">
                          <div className="flex flex-wrap items-center gap-2">
                            <Link to={sessionReportPath({ sessionId: session.id, reviewId: pass.reviewId, repo, branch })}>
                              <Button size="sm" variant="outline">
                                Open pass artifact
                              </Button>
                            </Link>
                            <span className="text-xs text-muted-foreground">{relativeTime(review.updatedAt)}</span>
                          </div>
                          {review.findings.length > 0 ? (
                            <div className="space-y-2">
                              {review.findings.map((finding, findingIndex) => (
                                <div key={`${findingKey(finding)}-${findingIndex}`} className="rounded-sm border border-border/70 bg-background px-3 py-2">
                                  <div className="flex flex-wrap items-center gap-2">
                                    <Badge variant="outline" className="rounded-full px-2 py-0.5 text-[10px] uppercase tracking-[0.08em]">
                                      {finding.severity}
                                    </Badge>
                                    <Badge variant="outline" className="rounded-full px-2 py-0.5 text-[10px] uppercase tracking-[0.08em]">
                                      {finding.category}
                                    </Badge>
                                  </div>
                                  <p className="mt-2 text-sm text-foreground">{finding.description}</p>
                                  {finding.locations[0]?.filePath ? (
                                    <p className="mt-1 text-xs text-muted-foreground">{finding.locations[0].filePath}</p>
                                  ) : null}
                                </div>
                              ))}
                            </div>
                          ) : (
                            <p className="text-sm text-muted-foreground">No findings recorded on this pass.</p>
                          )}
                        </div>
                      ) : (
                        <p className="text-sm text-muted-foreground">Pass details are unavailable.</p>
                      )}
                    </div>
                  ) : null}
                </div>
              );
            })}
          </div>
        </div>
      </Card>

      <div className="text-xs text-muted-foreground">
        Session page: <Link to={sessionBasePath} className="hover:text-foreground">{sessionBasePath}</Link>
      </div>
    </main>
  );
}

