    paths,
    adopt: {
      available: canAdopt,
      reason: canAdopt
        ? null
        : repoRoot
          ? 'Nimbus can only adopt reviewed changes once a session reaches an adoptable outcome.'
          : 'Open Review Studio from inside a git repository to adopt reviewed changes.',
      path: paths.adopt,
      modes: ['worktree', 'branch'],
    },
  };
