      includePatch: options?.includePatch,
      ...(typeof options?.maxBytes === 'number' ? { maxBytes: options.maxBytes } : {}),
    });
    const hasDiff = diff.summary.totalChanged > 0 || Boolean(diff.patch?.trim());
    return {
      sessionId: session.id,
