                    className="flex w-full flex-col gap-3 px-3 py-3 text-left md:flex-row md:items-center md:justify-between"
                  >
                    <div className="space-y-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <Badge variant="outline" className="rounded-full px-2 py-0.5 text-[10px] uppercase tracking-[0.08em]">
                          Pass {index + 1}
                        </Badge>
                        <Badge variant="outline" className="rounded-full px-2 py-0.5 text-[10px] uppercase tracking-[0.08em]">
                          {pass.reviewBasis}
                        </Badge>
                        <StatusPill status={pass.status} />
                        {pass.environmentRevision ? (
