}

.finding-details dt {
  color: #607284;
  font-size: 0.85rem;
}

.finding-details dd {
  white-space: pre-wrap;
}

.status-card h1,
.status-card h2 {
  margin-bottom: 0.4rem;
}

.evidence-list {
  list-style: none;
  padding: 1rem;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.8rem;
}

.evidence-list li {
