    createdAt: string;
    updatedAt: string;
    finishedAt: string | null;
    outcome: Record<string, unknown> | null;
    passes: Array<Record<string, unknown>>;
  }> = {}
): Record<string, unknown> {
  const id = overrides.id ?? 'ses_1';
  const latestReviewId = Object.prototype.hasOwnProperty.call(overrides, 'latestReviewId')
    ? overrides.latestReviewId
    : 'rev_1';
  const activeReviewId = Object.prototype.hasOwnProperty.call(overrides, 'activeReviewId')
    ? overrides.activeReviewId
    : latestReviewId;
  const currentReviewStatus = Object.prototype.hasOwnProperty.call(overrides, 'currentReviewStatus')
    ? overrides.currentReviewStatus
    : 'running';

  return {
    id,
    workspaceId: overrides.workspaceId ?? 'ws_1',
    anchorDeploymentId: overrides.anchorDeploymentId ?? 'dep_1',
    repo: overrides.repo ?? 'acme/web',
    branch: overrides.branch ?? 'main',
    initialReviewBasis: 'checkpoint',
