}

export function resolveStudioCheckpointWindowForTests(
  repoRoot: string,
  lastCheckpoints: 1 | 2 | 3
): StudioCheckpointWindowResolution {
  return resolveStudioCheckpointWindow(repoRoot, lastCheckpoints);
}

